export const linesPlanesExerciseBank: ExerciseSection[] = [
    {
        id: 'lines',
        title: say('Zuzenaren ekuazioak', 'Ecuaciones de la recta', 'معادلات المستقيم', 'Equations of a line'),
        items: [
            { id: 1, difficulty: 'easy', question: say('Idatzi $(2,-1,0)$ puntutik $(1,3,-2)$ norabidearekin pasatzen den zuzenaren parametrikoak.', 'Escribe las paramétricas de la recta por $(2,-1,0)$ con dirección $(1,3,-2)$.', 'اكتب المعادلات الوسيطية للمستقيم المار بـ $(2,-1,0)$ باتجاه $(1,3,-2)$.', 'Write the parametric equations of the line through $(2,-1,0)$ with direction $(1,3,-2)$.'), solution: same('$x=2+t,\\ y=-1+3t,\\ {z}=-2t$') },
            { id: 2, difficulty: 'easy', question: say('Zein puntu ematen du $t=3$ balioak $r$: $(1,1,1)+t(2,0,-1)$ zuzenean? Eman haren $x$.', '¿Qué punto de $r$: $(1,1,1)+t(2,0,-1)$ da $t=3$? Da su $x$.', 'أي نقطة من $r$: ‏$(1,1,1)+t(2,0,-1)$ تعطيها $t=3$؟ اكتب $x$.', 'Which point of $r$: $(1,1,1)+t(2,0,-1)$ does $t=3$ give? Give its $x$.'), solution: same('$(1+6,1,1-3)=(7,1,-2)$'), answer: { expected: n(7) } },
            { id: 3, difficulty: 'easy', question: say('Eman $\\frac{x}{2}=\\frac{y-1}{5}=\\frac{{z}+3}{-1}$ zuzenaren norabidearen bigarren koordenatua.', 'Da la segunda coordenada del director de $\\frac{x}{2}=\\frac{y-1}{5}=\\frac{{z}+3}{-1}$.', 'اكتب المركّبة الثانية لمتجه توجيه $\\frac{x}{2}=\\frac{y-1}{5}=\\frac{{z}+3}{-1}$.', 'Give the second coordinate of the direction of $\\frac{x}{2}=\\frac{y-1}{5}=\\frac{{z}+3}{-1}$.'), solution: same('$\\vec{u}=(2,5,-1)$'), answer: { expected: n(5) } },
            { id: 4, difficulty: 'easy', question: say('$A(1,2,3)$ eta $B(4,2,1)$ puntuetatik pasatzen den zuzena: eman $\\overrightarrow{AB}$ bektorearen hirugarren koordenatua.', 'Recta por $A(1,2,3)$ y $B(4,2,1)$: da la tercera coordenada de $\\overrightarrow{AB}$.', 'المستقيم المار بـ $A(1,2,3)$ و$B(4,2,1)$: اكتب المركّبة الثالثة لـ $\\overrightarrow{AB}$.', 'Line through $A(1,2,3)$ and $B(4,2,1)$: give the third coordinate of $\\overrightarrow{AB}$.'), solution: same('$\\overrightarrow{AB}=(3,0,-2)$'), answer: { expected: n(-2) } },
            { id: 5, difficulty: 'medium', question: say('$(3,5,-1)$ puntua $r$: $(1,1,1)+t(1,2,-1)$ zuzenean dago?', '¿Está $(3,5,-1)$ en $r$: $(1,1,1)+t(1,2,-1)$?', 'هل تقع $(3,5,-1)$ على $r$: ‏$(1,1,1)+t(1,2,-1)$؟', 'Is $(3,5,-1)$ on $r$: $(1,1,1)+t(1,2,-1)$?'), solution: say('Bai: $t=2$ eginez $(3,5,-1)$ ateratzen da.', 'Sí: con $t=2$ sale $(3,5,-1)$.', 'نعم: مع $t=2$ نحصل على $(3,5,-1)$.', 'Yes: $t=2$ gives $(3,5,-1)$.') },
            { id: 6, difficulty: 'medium', question: say('Idatzi $(0,2,-1)$ puntutik $(3,-1,4)$ norabidearekin pasatzen den zuzenaren ekuazio jarraitua.', 'Escribe la continua de la recta por $(0,2,-1)$ con dirección $(3,-1,4)$.', 'اكتب المعادلة المتصلة للمستقيم المار بـ $(0,2,-1)$ باتجاه $(3,-1,4)$.', 'Write the continuous equation of the line through $(0,2,-1)$ with direction $(3,-1,4)$.'), solution: same('$\\frac{x}{3}=\\frac{y-2}{-1}=\\frac{{z}+1}{4}$') },
            { id: 7, difficulty: 'medium', question: say('Idatzi $\\frac{x-1}{2}=\\frac{y}{3}=\\frac{{z}+2}{1}$ zuzenaren inplizituak.', 'Escribe unas implícitas de $\\frac{x-1}{2}=\\frac{y}{3}=\\frac{{z}+2}{1}$.', 'اكتب معادلتين ديكارتيتين لـ $\\frac{x-1}{2}=\\frac{y}{3}=\\frac{{z}+2}{1}$.', 'Write implicit equations of $\\frac{x-1}{2}=\\frac{y}{3}=\\frac{{z}+2}{1}$.'), solution: same('$3x-2y-3=0,\\ y-3{z}-6=0$') },
            { id: 8, difficulty: 'medium', question: say('$r$: $x+{z}=1$, $y-{z}=2$. Eman haren norabidearen lehen koordenatua, hirugarrena 1 bada.', '$r$: $x+{z}=1$, $y-{z}=2$. Da la primera coordenada de su director si la tercera es 1.', '$r$: ‏$x+{z}=1$ و$y-{z}=2$. اكتب المركّبة الأولى لاتجاهه إذا كانت الثالثة 1.', '$r$: $x+{z}=1$, $y-{z}=2$. Give the first coordinate of its direction if the third is 1.'), solution: same('$(1,0,1)\\times(0,1,-1)=(-1,1,1)$'), answer: { expected: n(-1) } },
            { id: 9, difficulty: 'hard', question: say('Aurkitu $r$: $2x-y=1$, $x+{z}=3$ zuzeneko puntua, $x=0$ duena. Eman haren ${z}$.', 'Halla el punto de $r$: $2x-y=1$, $x+{z}=3$ con $x=0$. Da su ${z}$.', 'أوجد نقطة $r$: ‏$2x-y=1$ و$x+{z}=3$ التي فيها $x=0$. اكتب ${z}$.', 'Find the point of $r$: $2x-y=1$, $x+{z}=3$ with $x=0$. Give its ${z}$.'), solution: same('$x=0\\ \\to\\ y=-1,\\ {z}=3$'), answer: { expected: n(3) } },
            { id: 10, difficulty: 'hard', question: say('$(m,n,0)$ puntua $r$: $(2,1,4)+t(1,1,2)$ zuzenean dago. Eman $m+n$.', '$(m,n,0)$ está en $r$: $(2,1,4)+t(1,1,2)$. Da $m+n$.', '$(m,n,0)$ تقع على $r$: ‏$(2,1,4)+t(1,1,2)$. اكتب $m+n$.', '$(m,n,0)$ lies on $r$: $(2,1,4)+t(1,1,2)$. Give $m+n$.'), solution: same('$4+2t=0\\ \\to\\ t=-2\\ \\to\\ (0,-1,0)\\qquad m+n=-1$'), answer: { expected: n(-1) } }
        ]
    },
    {
        id: 'planes',
        title: say('Planoaren ekuazioak', 'Ecuaciones del plano', 'معادلات المستوى', 'Equations of a plane'),
        items: [
            { id: 11, difficulty: 'easy', question: say('Eman $5x-{z}+2=0$ planoaren normalaren hirugarren koordenatua.', 'Da la tercera coordenada del normal de $5x-{z}+2=0$.', 'اكتب المركّبة الثالثة لناظم $5x-{z}+2=0$.', 'Give the third coordinate of the normal of $5x-{z}+2=0$.'), solution: same('$\\vec{n}=(5,0,-1)$'), answer: { expected: n(-1) } },
            { id: 12, difficulty: 'easy', question: say('$(1,1,1)$ puntua $2x-3y+{z}=0$ planoan dago?', '¿Está $(1,1,1)$ en $2x-3y+{z}=0$?', 'هل تقع $(1,1,1)$ في $2x-3y+{z}=0$؟', 'Is $(1,1,1)$ on $2x-3y+{z}=0$?'), solution: say('Bai: $2-3+1=0$.', 'Sí: $2-3+1=0$.', 'نعم: $2-3+1=0$.', 'Yes: $2-3+1=0$.') },
            { id: 13, difficulty: 'easy', question: say('Idatzi jatorritik $(1,2,3)$ normalarekin pasatzen den planoa.', 'Escribe el plano por el origen con normal $(1,2,3)$.', 'اكتب المستوى المار بالأصل وناظمه $(1,2,3)$.', 'Write the plane through the origin with normal $(1,2,3)$.'), solution: same('$x+2y+3{z}=0$') },
            { id: 14, difficulty: 'medium', question: say('$(1,2,-1)$ puntutik pasatzen den eta $3x+y-{z}=7$ planoaren paraleloa den planoa $3x+y-{z}+D=0$ da. Aurkitu $D$.', 'El plano por $(1,2,-1)$ paralelo a $3x+y-{z}=7$ es $3x+y-{z}+D=0$. Halla $D$.', 'المستوى المار بـ $(1,2,-1)$ الموازي لـ $3x+y-{z}=7$ هو $3x+y-{z}+D=0$. أوجد $D$.', 'The plane through $(1,2,-1)$ parallel to $3x+y-{z}=7$ is $3x+y-{z}+D=0$. Find $D$.'), solution: same('$3+2+1+D=0\\ \\to\\ D=-6$'), answer: { expected: n(-6) } },
            { id: 15, difficulty: 'medium', question: say('Eman $(2,1,0)$ eta $(0,1,3)$ norabideak dituen planoaren normalaren lehen koordenatua.', 'Da la primera coordenada del normal del plano con direcciones $(2,1,0)$ y $(0,1,3)$.', 'اكتب المركّبة الأولى لناظم المستوى ذي الاتجاهين $(2,1,0)$ و$(0,1,3)$.', 'Give the first coordinate of the normal of the plane with directions $(2,1,0)$ and $(0,1,3)$.'), solution: same('$(2,1,0)\\times(0,1,3)=(3,-6,2)$'), answer: { expected: n(3) } },
            { id: 16, difficulty: 'medium', question: say('Idatzi $(1,0,0)$ puntutik $(1,1,0)$ eta $(0,0,1)$ norabideekin pasatzen den planoaren parametrikoak.', 'Escribe las paramétricas del plano por $(1,0,0)$ con direcciones $(1,1,0)$ y $(0,0,1)$.', 'اكتب المعادلات الوسيطية للمستوى المار بـ $(1,0,0)$ باتجاهي $(1,1,0)$ و$(0,0,1)$.', 'Write the parametric equations of the plane through $(1,0,0)$ with directions $(1,1,0)$ and $(0,0,1)$.'), solution: same('$x=1+\\lambda,\\ y=\\lambda,\\ {z}=\\mu$') },
            { id: 17, difficulty: 'medium', question: say('$(1,0,0)$, $(0,3,0)$ eta $(0,0,2)$ puntuetatik pasatzen den planoa $6x+2y+3{z}=d$ da. Aurkitu $d$.', 'El plano por $(1,0,0)$, $(0,3,0)$ y $(0,0,2)$ es $6x+2y+3{z}=d$. Halla $d$.', 'المستوى المار بـ $(1,0,0)$ و$(0,3,0)$ و$(0,0,2)$ هو $6x+2y+3{z}=d$. أوجد $d$.', 'The plane through $(1,0,0)$, $(0,3,0)$ and $(0,0,2)$ is $6x+2y+3{z}=d$. Find $d$.'), solution: same('$6\\cdot 1=2\\cdot 3=3\\cdot 2=6$'), answer: { expected: n(6) } },
            { id: 18, difficulty: 'hard', question: say('Aurkitu $m$, $A(1,0,1)$, $B(2,1,0)$, $C(0,1,2)$ eta $D(m,2,1)$ plano berean egon daitezen.', 'Halla $m$ para que $A(1,0,1)$, $B(2,1,0)$, $C(0,1,2)$ y $D(m,2,1)$ estén en un plano.', 'أوجد $m$ لتقع $A(1,0,1)$ و$B(2,1,0)$ و$C(0,1,2)$ و$D(m,2,1)$ في مستوى واحد.', 'Find $m$ so that $A(1,0,1)$, $B(2,1,0)$, $C(0,1,2)$ and $D(m,2,1)$ lie in one plane.'), solution: same('$0+(m-1)+2+(m-1)-2-0=2m-2=0\\ \\to\\ m=1$'), answer: { expected: n(1) } },
            { id: 19, difficulty: 'hard', question: say('Aurkitu $r$: $(1,0,0)+t(0,1,1)$ zuzena duen eta jatorritik pasatzen den planoa.', 'Halla el plano que contiene a $r$: $(1,0,0)+t(0,1,1)$ y pasa por el origen.', 'أوجد المستوى الذي يحوي $r$: ‏$(1,0,0)+t(0,1,1)$ ويمر بالأصل.', 'Find the plane holding $r$: $(1,0,0)+t(0,1,1)$ and passing through the origin.'), solution: same('$(0,1,1)\\times(-1,0,0)=(0,-1,1)\\ \\to\\ y-{z}=0$') },
            { id: 20, difficulty: 'hard', question: say('Aurkitu $a$, $ax+y+{z}=1$ planoak $(t,1-t,0)$ zuzena izan dezan.', 'Halla $a$ para que el plano $ax+y+{z}=1$ contenga a la recta $(t,1-t,0)$.', 'أوجد $a$ ليحوي المستوى $ax+y+{z}=1$ المستقيم $(t,1-t,0)$.', 'Find $a$ so that the plane $ax+y+{z}=1$ holds the line $(t,1-t,0)$.'), solution: same('$(0,1,0)\\ \\to\\ 1=1\\qquad \\vec{u}\\cdot\\vec{n}=a-1=0\\ \\to\\ a=1$'), answer: { expected: n(1) } }
        ]
    },
    {
        id: 'two-lines',
        title: say('Bi zuzenen posizioa', 'Posición de dos rectas', 'وضع مستقيمين', 'Two lines'),
        items: [
            { id: 21, difficulty: 'easy', question: say('$(1,-2,3)$ eta $(-2,4,-6)$ norabideak paraleloak dira?', '¿Son paralelas las direcciones $(1,-2,3)$ y $(-2,4,-6)$?', 'هل الاتجاهان $(1,-2,3)$ و$(-2,4,-6)$ متوازيان؟', 'Are the directions $(1,-2,3)$ and $(-2,4,-6)$ parallel?'), solution: say('Bai: $(-2,4,-6)=-2\\,(1,-2,3)$.', 'Sí: $(-2,4,-6)=-2\\,(1,-2,3)$.', 'نعم: $(-2,4,-6)=-2\\,(1,-2,3)$.', 'Yes: $(-2,4,-6)=-2\\,(1,-2,3)$.') },
            { id: 22, difficulty: 'easy', question: say('Norabideak paraleloak ez badira eta $[\\overrightarrow{AB},\\vec{u},\\vec{v}]=0$ bada, nolakoak dira zuzenak?', 'Si los directores no son paralelos y $[\\overrightarrow{AB},\\vec{u},\\vec{v}]=0$, ¿cómo son las rectas?', 'إذا لم يتوازَ الاتجاهان وكان $[\\overrightarrow{AB},\\vec{u},\\vec{v}]=0$ فما وضع المستقيمين؟', 'If the directions are not parallel and $[\\overrightarrow{AB},\\vec{u},\\vec{v}]=0$, how are the lines?'), solution: say('Ebakitzaileak: plano batean daude eta ez dira paraleloak.', 'Secantes: están en un plano y no son paralelas.', 'متقاطعان: في مستوى واحد وغير متوازيين.', 'Intersecting: they lie in one plane and are not parallel.') },
            { id: 23, difficulty: 'easy', question: say('Bat datoz $r$: $(0,0,0)+t(1,1,1)$ eta $s$: $(2,2,2)+\\lambda(3,3,3)$?', '¿Coinciden $r$: $(0,0,0)+t(1,1,1)$ y $s$: $(2,2,2)+\\lambda(3,3,3)$?', 'هل ينطبق $r$: ‏$(0,0,0)+t(1,1,1)$ و$s$: ‏$(2,2,2)+\\lambda(3,3,3)$؟', 'Do $r$: $(0,0,0)+t(1,1,1)$ and $s$: $(2,2,2)+\\lambda(3,3,3)$ coincide?'), solution: say('Bai: norabide proportzionalak, eta $(2,2,2)$ puntua $r$ zuzenean dago $t=2$ denean.', 'Sí: directores proporcionales y $(2,2,2)$ está en $r$ con $t=2$.', 'نعم: اتجاهان متناسبان و$(2,2,2)$ على $r$ عندما $t=2$.', 'Yes: proportional directions, and $(2,2,2)$ is on $r$ with $t=2$.') },
            { id: 24, difficulty: 'medium', question: say('Kalkulatu biderkadura mistoa $r$: $(1,0,0)+t(0,1,0)$ eta $s$: $(0,0,1)+\\lambda(1,0,0)$ zuzenetarako.', 'Calcula el producto mixto para $r$: $(1,0,0)+t(0,1,0)$ y $s$: $(0,0,1)+\\lambda(1,0,0)$.', 'احسب الجداء المختلط لـ $r$: ‏$(1,0,0)+t(0,1,0)$ و$s$: ‏$(0,0,1)+\\lambda(1,0,0)$.', 'Work out the scalar triple product for $r$: $(1,0,0)+t(0,1,0)$ and $s$: $(0,0,1)+\\lambda(1,0,0)$.'), solution: say('$0+0+0-1-0-0=-1$ da: gurutzatu egiten dira.', 'Vale $0+0+0-1-0-0=-1$: se cruzan.', 'يساوي $0+0+0-1-0-0=-1$: متخالفان.', 'It is $0+0+0-1-0-0=-1$: they are skew.'), answer: { expected: n(-1) } },
            { id: 25, difficulty: 'medium', question: say('Eman $r$: $(t,0,0)$ eta $s$: $(2,\\lambda,0)$ zuzenen ebaki-puntuaren $x$.', 'Da la $x$ del punto de corte de $r$: $(t,0,0)$ y $s$: $(2,\\lambda,0)$.', 'اكتب $x$ لنقطة تقاطع $r$: ‏$(t,0,0)$ و$s$: ‏$(2,\\lambda,0)$.', 'Give the $x$ of the meeting point of $r$: $(t,0,0)$ and $s$: $(2,\\lambda,0)$.'), solution: same('$t=2,\\ \\lambda=0\\ \\to\\ (2,0,0)$'), answer: { expected: n(2) } },
            { id: 26, difficulty: 'medium', question: say('Aurkitu $m$, $(m,2,1)$ norabidea $(6,4,2)$ norabidearen paraleloa izan dadin.', 'Halla $m$ para que la dirección $(m,2,1)$ sea paralela a $(6,4,2)$.', 'أوجد $m$ ليكون الاتجاه $(m,2,1)$ موازيًا لـ $(6,4,2)$.', 'Find $m$ so that the direction $(m,2,1)$ is parallel to $(6,4,2)$.'), solution: same('$(m,2,1)=\\frac{1}{2}\\,(6,4,2)\\ \\to\\ m=3$'), answer: { expected: n(3) } },
            { id: 27, difficulty: 'medium', question: say('Ebakitzen dira $r$: $(0,0,0)+t(1,1,0)$ eta $s$: $(1,0,0)+\\lambda(0,1,0)$?', '¿Se cortan $r$: $(0,0,0)+t(1,1,0)$ y $s$: $(1,0,0)+\\lambda(0,1,0)$?', 'هل يتقاطع $r$: ‏$(0,0,0)+t(1,1,0)$ و$s$: ‏$(1,0,0)+\\lambda(0,1,0)$؟', 'Do $r$: $(0,0,0)+t(1,1,0)$ and $s$: $(1,0,0)+\\lambda(0,1,0)$ meet?'), solution: say('Bai: biak ${z}=0$ planoan daude; $(1,1,0)$ puntuan ebakitzen dira.', 'Sí: las dos están en ${z}=0$; se cortan en $(1,1,0)$.', 'نعم: كلاهما في ${z}=0$؛ يتقاطعان في $(1,1,0)$.', 'Yes: both lie in ${z}=0$; they meet at $(1,1,0)$.') },
            { id: 28, difficulty: 'hard', question: say('Aurkitu $k$, $r$: $(1,1,0)+t(1,0,1)$ eta $s$: $(0,0,k)+\\lambda(1,1,0)$ ebaki daitezen.', 'Halla $k$ para que $r$: $(1,1,0)+t(1,0,1)$ y $s$: $(0,0,k)+\\lambda(1,1,0)$ se corten.', 'أوجد $k$ ليتقاطع $r$: ‏$(1,1,0)+t(1,0,1)$ و$s$: ‏$(0,0,k)+\\lambda(1,1,0)$.', 'Find $k$ so that $r$: $(1,1,0)+t(1,0,1)$ and $s$: $(0,0,k)+\\lambda(1,1,0)$ meet.'), solution: same('$0-1+k-0+1-0=k=0$'), answer: { expected: n(0) } },
            { id: 29, difficulty: 'hard', question: say('Eman $r$: $(1,2,3)+t(1,0,-1)$ eta $s$: $(0,2,0)+\\lambda(1,0,1)$ zuzenen ebaki-puntuaren ${z}$.', 'Da la ${z}$ del punto de corte de $r$: $(1,2,3)+t(1,0,-1)$ y $s$: $(0,2,0)+\\lambda(1,0,1)$.', 'اكتب ${z}$ لنقطة تقاطع $r$: ‏$(1,2,3)+t(1,0,-1)$ و$s$: ‏$(0,2,0)+\\lambda(1,0,1)$.', 'Give the ${z}$ of the meeting point of $r$: $(1,2,3)+t(1,0,-1)$ and $s$: $(0,2,0)+\\lambda(1,0,1)$.'), solution: same('$1+t=\\lambda,\\ 3-t=\\lambda\\ \\to\\ t=1\\ \\to\\ (2,2,2)$'), answer: { expected: n(2) } },
            { id: 30, difficulty: 'hard', question: say('Idatzi $(1,1,1)$ puntutik pasatzen den eta $s$: $x=2t$, $y=1-t$, ${z}=3$ zuzenaren paraleloa den zuzena.', 'Escribe la recta por $(1,1,1)$ paralela a $s$: $x=2t$, $y=1-t$, ${z}=3$.', 'اكتب المستقيم المار بـ $(1,1,1)$ الموازي لـ $s$: ‏$x=2t$ و$y=1-t$ و${z}=3$.', 'Write the line through $(1,1,1)$ parallel to $s$: $x=2t$, $y=1-t$, ${z}=3$.'), solution: same('$(x,y,{z})=(1,1,1)+t\\,(2,-1,0)$') }
        ]
    },
    {
        id: 'line-plane',
        title: say('Zuzena eta planoa', 'Recta y plano', 'مستقيم ومستوى', 'A line and a plane'),
        items: [
            { id: 31, difficulty: 'easy', question: say('$(1,1,1)$ norabidea duen zuzena $x-y=4$ planoaren paraleloa da?', '¿Es paralela al plano $x-y=4$ la recta con dirección $(1,1,1)$?', 'هل المستقيم ذو الاتجاه $(1,1,1)$ موازٍ للمستوى $x-y=4$؟', 'Is the line with direction $(1,1,1)$ parallel to the plane $x-y=4$?'), solution: say('Paraleloa edo planoan: $\\vec{u}\\cdot\\vec{n}=1-1+0=0$.', 'Paralela o contenida: $\\vec{u}\\cdot\\vec{n}=1-1+0=0$.', 'موازٍ أو محتوى: $\\vec{u}\\cdot\\vec{n}=1-1+0=0$.', 'Parallel or inside: $\\vec{u}\\cdot\\vec{n}=1-1+0=0$.') },
            { id: 32, difficulty: 'easy', question: say('$r$: $(t,t,t)$ eta $x+y+{z}=6$: eman ebaki-puntuaren $t$.', '$r$: $(t,t,t)$ y $x+y+{z}=6$: da el $t$ del punto de corte.', '$r$: ‏$(t,t,t)$ و$x+y+{z}=6$: اكتب $t$ لنقطة التقاطع.', '$r$: $(t,t,t)$ and $x+y+{z}=6$: give the $t$ of the meeting point.'), solution: same('$3t=6\\ \\to\\ t=2$'), answer: { expected: n(2) } },
            { id: 33, difficulty: 'easy', question: say('Kalkulatu $\\vec{u}\\cdot\\vec{n}$, $\\vec{u}=(2,0,1)$ eta $\\pi$: $x+3y-2{z}=0$ izanik.', 'Calcula $\\vec{u}\\cdot\\vec{n}$ con $\\vec{u}=(2,0,1)$ y $\\pi$: $x+3y-2{z}=0$.', 'احسب $\\vec{u}\\cdot\\vec{n}$ حيث $\\vec{u}=(2,0,1)$ و$\\pi$: ‏$x+3y-2{z}=0$.', 'Work out $\\vec{u}\\cdot\\vec{n}$ with $\\vec{u}=(2,0,1)$ and $\\pi$: $x+3y-2{z}=0$.'), solution: same('$2+0-2=0$'), answer: { expected: n(0) } },
            { id: 34, difficulty: 'medium', question: say('Non ebakitzen du $r$: $(1+t,2,3-t)$ zuzenak $\\pi$: $x+{z}=5$ planoa?', '¿Dónde corta $r$: $(1+t,2,3-t)$ al plano $\\pi$: $x+{z}=5$?', 'أين يقطع $r$: ‏$(1+t,2,3-t)$ المستوى $\\pi$: ‏$x+{z}=5$؟', 'Where does $r$: $(1+t,2,3-t)$ meet $\\pi$: $x+{z}=5$?'), solution: say('Inon ez: $(1+t)+(3-t)=4$ beti, eta $4\\neq 5$; zuzena paraleloa da.', 'En ningún sitio: $(1+t)+(3-t)=4$ siempre, y $4\\neq 5$; la recta es paralela.', 'لا مكان: ‏$(1+t)+(3-t)=4$ دائمًا و$4\\neq 5$؛ المستقيم موازٍ.', 'Nowhere: $(1+t)+(3-t)=4$ always, and $4\\neq 5$; the line is parallel.') },
            { id: 35, difficulty: 'medium', question: say('Eman $r$: $(2t,1,1-t)$ zuzenaren eta $\\pi$: $x-y+{z}=3$ planoaren ebaki-puntuaren $x$.', 'Da la $x$ del punto de corte de $r$: $(2t,1,1-t)$ con $\\pi$: $x-y+{z}=3$.', 'اكتب $x$ لنقطة تقاطع $r$: ‏$(2t,1,1-t)$ مع $\\pi$: ‏$x-y+{z}=3$.', 'Give the $x$ of the meeting point of $r$: $(2t,1,1-t)$ and $\\pi$: $x-y+{z}=3$.'), solution: same('$2t-1+1-t=3\\ \\to\\ t=3\\ \\to\\ x=6$'), answer: { expected: n(6) } },
            { id: 36, difficulty: 'medium', question: say('$r$: $(1,0,0)+t(1,1,1)$ zuzena $\\pi$: $x-y=1$ planoan dago?', '¿Está $r$: $(1,0,0)+t(1,1,1)$ en $\\pi$: $x-y=1$?', 'هل $r$: ‏$(1,0,0)+t(1,1,1)$ في $\\pi$: ‏$x-y=1$؟', 'Does $r$: $(1,0,0)+t(1,1,1)$ lie in $\\pi$: $x-y=1$?'), solution: say('Bai: $\\vec{u}\\cdot\\vec{n}=0$ eta $1-0=1$.', 'Sí: $\\vec{u}\\cdot\\vec{n}=0$ y $1-0=1$.', 'نعم: $\\vec{u}\\cdot\\vec{n}=0$ و$1-0=1$.', 'Yes: $\\vec{u}\\cdot\\vec{n}=0$ and $1-0=1$.') },
            { id: 37, difficulty: 'medium', question: say('$(x-1)+k\\,{z}=0$ sortan, aurkitu $(3,0,2)$ puntutik pasatzen den planoaren $k$.', 'En el haz $(x-1)+k\\,{z}=0$, halla el $k$ del plano que pasa por $(3,0,2)$.', 'في الحزمة $(x-1)+k\\,{z}=0$ أوجد $k$ للمستوى المار بـ $(3,0,2)$.', 'In the pencil $(x-1)+k\\,{z}=0$, find the $k$ of the plane through $(3,0,2)$.'), solution: same('$2+2k=0\\ \\to\\ k=-1$'), answer: { expected: n(-1) } },
            { id: 38, difficulty: 'hard', question: say('Aurkitu $m$, $r$: $(1,m,0)+t(1,1,1)$ zuzena $\\pi$: $x-y=0$ planoan egon dadin.', 'Halla $m$ para que $r$: $(1,m,0)+t(1,1,1)$ esté en $\\pi$: $x-y=0$.', 'أوجد $m$ ليكون $r$: ‏$(1,m,0)+t(1,1,1)$ في $\\pi$: ‏$x-y=0$.', 'Find $m$ so that $r$: $(1,m,0)+t(1,1,1)$ lies in $\\pi$: $x-y=0$.'), solution: same('$\\vec{u}\\cdot\\vec{n}=1-1=0\\qquad 1-m=0\\ \\to\\ m=1$'), answer: { expected: n(1) } },
            { id: 39, difficulty: 'hard', question: say('Eman $\\frac{x-1}{2}=\\frac{y}{1}=\\frac{{z}+1}{1}$ zuzenaren eta $x+y+{z}=8$ planoaren ebaki-puntuaren $x$.', 'Da la $x$ del punto de corte de $\\frac{x-1}{2}=\\frac{y}{1}=\\frac{{z}+1}{1}$ con $x+y+{z}=8$.', 'اكتب $x$ لنقطة تقاطع $\\frac{x-1}{2}=\\frac{y}{1}=\\frac{{z}+1}{1}$ مع $x+y+{z}=8$.', 'Give the $x$ of the meeting point of $\\frac{x-1}{2}=\\frac{y}{1}=\\frac{{z}+1}{1}$ and $x+y+{z}=8$.'), solution: same('$1+2t+t-1+t=8\\ \\to\\ t=2\\ \\to\\ x=5$'), answer: { expected: n(5) } },
            { id: 40, difficulty: 'hard', question: say('$x=0$, $y=1$ zuzena duen eta $(2,0,0)$ puntutik pasatzen den planoa $x+k\\,(y-1)=0$ da. Aurkitu $k$.', 'El plano que contiene a $x=0$, $y=1$ y pasa por $(2,0,0)$ es $x+k\\,(y-1)=0$. Halla $k$.', 'المستوى الذي يحوي $x=0$ و$y=1$ ويمر بـ $(2,0,0)$ هو $x+k\\,(y-1)=0$. أوجد $k$.', 'The plane holding $x=0$, $y=1$ and passing through $(2,0,0)$ is $x+k\\,(y-1)=0$. Find $k$.'), solution: same('$2+k\\,(0-1)=0\\ \\to\\ k=2$'), answer: { expected: n(2) } }
        ]
    },
    {
        id: 'planes-position',
        title: say('Planoen posizioa', 'Posición de planos', 'وضع المستويات', 'Position of planes'),
        items: [
            { id: 41, difficulty: 'easy', question: say('$x+y=1$ eta $x+y=4$ paraleloak dira?', '¿Son paralelos $x+y=1$ y $x+y=4$?', 'هل $x+y=1$ و$x+y=4$ متوازيان؟', 'Are $x+y=1$ and $x+y=4$ parallel?'), solution: say('Bai: normal bera eta gai aske desberdina.', 'Sí: el mismo normal y distinto término independiente.', 'نعم: الناظم نفسه وحد ثابت مختلف.', 'Yes: the same normal and a different constant term.') },
            { id: 42, difficulty: 'easy', question: say('Nolakoak dira $2x-y+{z}=3$ eta $x+y=0$?', '¿Cómo son $2x-y+{z}=3$ y $x+y=0$?', 'ما وضع $2x-y+{z}=3$ و$x+y=0$؟', 'How are $2x-y+{z}=3$ and $x+y=0$?'), solution: say('Ebakitzaileak: normalak ez dira proportzionalak, eta zuzen batean ebakitzen dute elkar.', 'Secantes: los normales no son proporcionales y se cortan en una recta.', 'متقاطعان: الناظمان غير متناسبين ويتقاطعان في مستقيم.', 'Secant: the normals are not proportional and they meet in a line.') },
            { id: 43, difficulty: 'easy', question: say('$\\operatorname{rg}M=\\operatorname{rg}M^*=2$ bada, nolakoak dira hiru planoak?', 'Si $\\operatorname{rg}M=\\operatorname{rg}M^*=2$, ¿cómo son los tres planos?', 'إذا كان $\\operatorname{rg}M=\\operatorname{rg}M^*=2$ فما وضع المستويات الثلاثة؟', 'If $\\operatorname{rg}M=\\operatorname{rg}M^*=2$, how are the three planes?'), solution: say('Zuzen bat dute komunean.', 'Tienen una recta en común.', 'لها مستقيم مشترك.', 'They have a line in common.') },
            { id: 44, difficulty: 'medium', question: say('Aurkitu $m$, $x+my+{z}=0$ eta $2x+4y+2{z}=1$ paraleloak izan daitezen.', 'Halla $m$ para que $x+my+{z}=0$ y $2x+4y+2{z}=1$ sean paralelos.', 'أوجد $m$ ليكون $x+my+{z}=0$ و$2x+4y+2{z}=1$ متوازيين.', 'Find $m$ so that $x+my+{z}=0$ and $2x+4y+2{z}=1$ are parallel.'), solution: same('$2m=4\\ \\to\\ m=2$'), answer: { expected: n(2) } },
            { id: 45, difficulty: 'medium', question: say('Eman $x=1$, $y=2$ eta ${z}=x+y$ planoen ebaki-puntuaren ${z}$.', 'Da la ${z}$ del punto de corte de $x=1$, $y=2$ y ${z}=x+y$.', 'اكتب ${z}$ لنقطة تقاطع $x=1$ و$y=2$ و${z}=x+y$.', 'Give the ${z}$ of the point where $x=1$, $y=2$ and ${z}=x+y$ meet.'), solution: same('${z}=1+2=3$'), answer: { expected: n(3) } },
            { id: 46, difficulty: 'medium', question: say('Kalkulatu $\\det M$, $x+y+{z}=1$, $x-y+{z}=0$ eta $x+y-{z}=2$ planoetarako.', 'Calcula $\\det M$ para $x+y+{z}=1$, $x-y+{z}=0$ y $x+y-{z}=2$.', 'احسب $\\det M$ للمستويات $x+y+{z}=1$ و$x-y+{z}=0$ و$x+y-{z}=2$.', 'Work out $\\det M$ for $x+y+{z}=1$, $x-y+{z}=0$ and $x+y-{z}=2$.'), solution: same('$1+1+1+1-1+1=4$'), answer: { expected: n(4) } },
            { id: 47, difficulty: 'medium', question: say('Aurkitu $x+y=2$ eta ${z}=1$ planoen ebaki-zuzenaren norabidea.', 'Halla la dirección de la recta de corte de $x+y=2$ y ${z}=1$.', 'أوجد اتجاه مستقيم تقاطع $x+y=2$ و${z}=1$.', 'Find the direction of the line where $x+y=2$ and ${z}=1$ meet.'), solution: same('$(1,1,0)\\times(0,0,1)=(1,-1,0)$') },
            { id: 48, difficulty: 'hard', question: say('$a$ parametroaren zein baliotarako dira paraleloak $ax+2y-{z}=1$ eta $3x+6y-3{z}=2$?', '¿Para qué $a$ son paralelos $ax+2y-{z}=1$ y $3x+6y-3{z}=2$?', 'لأي $a$ يتوازى $ax+2y-{z}=1$ و$3x+6y-3{z}=2$؟', 'For which $a$ are $ax+2y-{z}=1$ and $3x+6y-3{z}=2$ parallel?'), solution: same('$3a=3\\ \\to\\ a=1\\qquad 3\\cdot 1=3\\neq 2$'), answer: { expected: n(1) } },
            { id: 49, difficulty: 'hard', question: say('Eman $x+y+{z}=6$, $x-y=0$ eta $y-{z}=0$ planoen ebaki-puntuaren $x$.', 'Da la $x$ del punto de corte de $x+y+{z}=6$, $x-y=0$ y $y-{z}=0$.', 'اكتب $x$ لنقطة تقاطع $x+y+{z}=6$ و$x-y=0$ و$y-{z}=0$.', 'Give the $x$ of the point where $x+y+{z}=6$, $x-y=0$ and $y-{z}=0$ meet.'), solution: same('$x=y={z}\\ \\to\\ 3x=6\\ \\to\\ x=2$'), answer: { expected: n(2) } },
            { id: 50, difficulty: 'hard', question: say('$a$ parametroaren zein baliotarako dute zuzen bat komunean $x+y+{z}=a$, $x-y=0$ eta $2x+{z}=1$ planoek?', '¿Para qué $a$ tienen una recta en común $x+y+{z}=a$, $x-y=0$ y $2x+{z}=1$?', 'لأي $a$ يكون للمستويات $x+y+{z}=a$ و$x-y=0$ و$2x+{z}=1$ مستقيم مشترك؟', 'For which $a$ do $x+y+{z}=a$, $x-y=0$ and $2x+{z}=1$ have a line in common?'), solution: same('$\\det M=0\\qquad(1,1,1)=-(1,-1,0)+(2,0,1)\\ \\to\\ a=-1\\cdot 0+1\\cdot 1=1$'), answer: { expected: n(1) } }
        ]
    }
]
